const HEADLINE_LINE1 = "WMS 현장 전산 경험을 녹여";
const HEADLINE_LINE2 = "백엔드 중심의 실무형 풀스택을 만드는 개발자, 강민건";
const HEADLINE_STEP = 18; // 글자당 등장 간격(ms)
const HEADLINE_START = 80;
const LINE2_START = HEADLINE_START + HEADLINE_LINE1.length * HEADLINE_STEP;
const AFTER_HEADLINE = LINE2_START + HEADLINE_LINE2.length * HEADLINE_STEP + 40;

function RevealChars({ text, startDelay }) {
  // 글자 하나하나를 inline-block span으로 감싸면 그 사이 스페이스가 줄 시작/끝
  // 여백 취급돼 사라지거나(NBSP로 때우면 이번엔 줄바꿈 지점이 없어져 단어 중간이
  // 잘림) 하므로, 단어 단위로 한 번 더 묶어(inline-block) 단어는 항상 통째로
  // 넘어가게 하고, 단어 사이 스페이스는 일반 텍스트 노드로 그대로 둔다.
  let i = 0;
  const nodes = [];
  const words = text.split(" ");
  words.forEach((word, wi) => {
    nodes.push(
      <span key={`w${wi}`} className="inline-block">
        {word.split("").map((ch) => {
          const node = (
            <span key={i} className="animate-in inline-block" style={{ animationDelay: `${startDelay + i * HEADLINE_STEP}ms` }}>
              {ch}
            </span>
          );
          i += 1;
          return node;
        })}
      </span>
    );
    if (wi < words.length - 1) {
      nodes.push(" ");
      i += 1;
    }
  });
  return nodes;
}

